:"g/dL","flag":"L"},{"label":"Platelets","value":"212","unit":"K/µL"},{"label":"INR","value":"1.1"},{"label":"D-dimer","value":"3.8","unit":"µg/mL FEU","flag":"H"},{"label":"Troponin I","value":"0.02","unit":"ng/mL"}]}],"timePointId":"tp_1400"},{"id":"tab_orders","kind":"orders","title":"Orders","blocks":[{"kind":"markdown","value":"- Enoxaparin 40 mg subcutaneous daily (first dose due 0900, not yet documented as given)\n- Oxycodone 5 mg PO every 4 h PRN pain\n- Physical therapy twice daily, weight bearing as tolerated\n- Sequential compression devices bilaterally while in bed"}]}]}$json$::jsonb,
